tool_schemas.implementation:
def tavily_search(query, search_depth=None, max_results=None, include_domains=None, exclude_domains=None, include_answer=None, include_raw_content=None, include_images=None, time_range=None, start_date=None, end_date=None, idempotency_key=None, **_extra):
    import json, os, datetime
    import time, hashlib, uuid
    from urllib.parse import urlparse, urlunparse, parse_qsl, urlencode

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0424000" if __import__("os").path.isdir("./environment_mix/0424000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an ISO 8601 datetime string")
        try:
            # Accept trailing Z
            ss = s.replace("Z", "+00:00")
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            raise ValueError(f"{field} must be an ISO 8601 datetime string")

    def _valid_host(h):
        if not isinstance(h, str) or not h:
            return False
        hh = h.strip().lower()
        if len(hh) > 253:
            return False
        # allow simple hostname chars
        for ch in hh:
            if not (ch.isalnum() or ch in ".-"):
                return False
        if ".." in hh or hh.startswith("-") or hh.endswith("-") or hh.startswith(".") or hh.endswith("."):
            return False
        return True

    def _normalize_url(url):
        if not isinstance(url, str) or not url.strip():
            raise ValueError("url must be a non-empty string")
        u = url.strip()
        p = urlparse(u)
        if p.scheme not in ("http", "https"):
            raise ValueError("url must be http(s)")
        if not p.netloc:
            raise ValueError("url must include a host")
        host = p.hostname.lower() if p.hostname else ""
        if not _valid_host(host):
            raise ValueError("url host is malformed")
        # drop default ports
        netloc = host
        if p.port and not ((p.scheme == "http" and p.port == 80) or (p.scheme == "https" and p.port == 443)):
            netloc = f"{host}:{p.port}"
        path = p.path or "/"
        # collapse multiple slashes (basic)
        while "//" in path:
            path = path.replace("//", "/")
        # sort query params for determinism
        q = urlencode(sorted(parse_qsl(p.query, keep_blank_values=True)))
        canon = urlunparse((p.scheme.lower(), netloc, path, "", q, ""))  # strip fragment
        url_hash = hashlib.sha256(canon.encode("utf-8")).hexdigest()
        return canon, url_hash, host

    def _log_request(requests_rows, api_key_id, tool, status, http_status, idempotency_key, input_obj, normalized_target, response_obj, error_code, error_message, tokens_used, result_count, started_at, finished_at):
        rid = _new_id("req")
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool": tool,
            "status": status,
            "idempotency_key": idempotency_key,
            "input": input_obj,
            "normalized_target": normalized_target,
            "response": response_obj,
            "error_code": error_code,
            "error_message": error_message,
            "http_status": http_status,
            "tokens_used": int(tokens_used),
            "result_count": result_count,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        requests_rows.append(row)
        return row

    def _find_working_key(api_keys_rows, tool):
        # Ambient auth: choose any active key that can serve the tool.
        for k in api_keys_rows:
            if k.get("status") != "active":
                continue
            allowed = k.get("allowed_tools")
            if isinstance(allowed, list) and len(allowed) > 0 and tool not in allowed:
                continue
            # validate basic limits presence
            if not isinstance(k.get("rate_limit_rpm"), int) or k["rate_limit_rpm"] < 1:
                continue
            if not isinstance(k.get("monthly_request_quota"), int) or k["monthly_request_quota"] < 0:
                continue
            if not isinstance(k.get("monthly_token_quota"), int) or k["monthly_token_quota"] < 0:
                continue
            if not isinstance(k.get("usage_requests"), int) or k["usage_requests"] < 0:
                continue
            if not isinstance(k.get("usage_tokens"), int) or k["usage_tokens"] < 0:
                continue
            if not isinstance(k.get("usage_month"), str) or len(k["usage_month"]) != 7:
                continue
            return k
        return None

    def _reset_month_if_needed(k):
        month = now.strftime("%Y-%m")
        if k.get("usage_month") != month:
            k["usage_month"] = month
            k["usage_requests"] = 0
            k["usage_tokens"] = 0

    def _enforce_rate_limit(api_key_id, api_key_row, requests_rows, tool):
        # Requests per minute based on created_at (all statuses), for this api_key_id
        rpm = api_key_row.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1:
            return False  # treat as unusable upstream, but key selection should have avoided
        window_start = (now - datetime.timedelta(seconds=60)).isoformat()
        cnt = 0
        for r in requests_rows:
            if r.get("api_key_id") != api_key_id:
                continue
            ca = r.get("created_at")
            if isinstance(ca, str) and ca >= window_start:
                cnt += 1
        return cnt < rpm

    def _quota_allows(api_key_row, add_requests=1, add_tokens=0):
        mrq = api_key_row.get("monthly_request_quota", 0)
        mtq = api_key_row.get("monthly_token_quota", 0)
        ur = api_key_row.get("usage_requests", 0)
        ut = api_key_row.get("usage_tokens", 0)
        if not isinstance(mrq, int) or not isinstance(mtq, int) or not isinstance(ur, int) or not isinstance(ut, int):
            return False
        if mrq > 0 and ur + add_requests > mrq:
            return False
        if mtq > 0 and ut + add_tokens > mtq:
            return False
        return True

    def _charge_usage(api_key_row, tokens_used):
        api_key_row["usage_requests"] = int(api_key_row.get("usage_requests", 0)) + 1
        api_key_row["usage_tokens"] = int(api_key_row.get("usage_tokens", 0)) + int(tokens_used)
        api_key_row["last_used_at"] = now_iso
        api_key_row["updated_at"] = now_iso

    def _estimate_tokens(inp, n_results):
        # Simple normalized cost model.
        qlen = len(inp.get("query", "") or "")
        base = 20
        depth = inp.get("search_depth") or "basic"
        depth_mul = 2 if depth == "advanced" else 1
        raw = 10 if inp.get("include_raw_content") else 0
        ans = 15 if inp.get("include_answer") else 0
        imgs = 5 if inp.get("include_images") else 0
        return int((base + qlen // 8 + (n_results * (6 + raw + imgs)) + ans) * depth_mul)

    def _upsert_web_resource(web_resources_rows, canonical_url, url_hash, host, title=None, description=None, content_text=None, content_html=None, mime_type=None, http_status_last=None, status=None, fetched_at=None):
        # Find by url_hash
        existing = None
        for w in web_resources_rows:
            if w.get("url_hash") == url_hash:
                existing = w
                break
        if existing is None:
            wid = _new_id("wr")
            row = {
                "id": wid,
                "canonical_url": canonical_url,
                "url_hash": url_hash,
                "host": host,
                "title": title,
                "description": description,
                "content_text": content_text,
                "content_html": content_html,
                "content_storage_url": None,
                "content_mime_type": mime_type,
                "http_status_last": http_status_last,
                "fetched_at": fetched_at,
                "first_seen_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            # lifecycle field exists in schema but not in fields list; still store it for transitions.
            if status is None:
                status = "discovered"
            row["status"] = status
            web_resources_rows.append(row)
            return row, True
        # update mutable fields
        existing["canonical_url"] = canonical_url
        existing["host"] = host
        if title is not None:
            existing["title"] = title
        if description is not None:
            existing["description"] = description
        if content_text is not None:
            existing["content_text"] = content_text
        if content_html is not None:
            existing["content_html"] = content_html
        if mime_type is not None:
            existing["content_mime_type"] = mime_type
        if http_status_last is not None:
            existing["http_status_last"] = http_status_last
        if fetched_at is not None:
            existing["fetched_at"] = fetched_at
        if status is not None:
            existing["status"] = status
        existing["updated_at"] = now_iso
        return existing, False

    def _ensure_request_result(request_results_rows, request_id, web_resource_id, result_type, rank=None, score=None, metadata=None):
        # enforce unique(request_id, web_resource_id, result_type)
        existing = None
        for rr in request_results_rows:
            if rr.get("request_id") == request_id and rr.get("web_resource_id") == web_resource_id and rr.get("result_type") == result_type:
                existing = rr
                break
        if existing is None:
            rrid = _new_id("rr")
            row = {
                "id": rrid,
                "request_id": request_id,
                "web_resource_id": web_resource_id,
                "result_type": result_type,
                "rank": rank,
                "score": score,
                "source_url_id": None,
                "depth": None,
                "anchor_text": None,
                "metadata": metadata if isinstance(metadata, dict) else {},
                "created_at": now_iso,
                "updated_at": now_iso,
                "status": "active",
            }
            request_results_rows.append(row)
            return row, True
        # keep best (lowest) rank if provided
        if rank is not None:
            er = existing.get("rank")
            if er is None or (isinstance(er, int) and rank < er):
                existing["rank"] = rank
        if score is not None:
            existing["score"] = score
        if isinstance(metadata, dict):
            # merge
            m = existing.get("metadata")
            if not isinstance(m, dict):
                m = {}
            m.update(metadata)
            existing["metadata"] = m
        existing["updated_at"] = now_iso
        return existing, False

    # ---- Validate inputs ----
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query is required and must be a non-empty string", field="query")

    if search_depth is not None and search_depth not in ("basic", "advanced"):
        return _err("VALIDATION_ERROR", "search_depth must be one of: basic, advanced", field="search_depth")
    if max_results is not None:
        if not isinstance(max_results, int):
            return _err("VALIDATION_ERROR", "max_results must be an integer", field="max_results")
        if max_results < 1:
            return _err("VALIDATION_ERROR", "max_results must be >= 1", field="max_results")
    else:
        max_results = 5

    if include_domains is not None:
        if not isinstance(include_domains, list) or any(not isinstance(x, str) for x in include_domains):
            return _err("VALIDATION_ERROR", "include_domains must be an array of strings", field="include_domains")
        if any(not _valid_host(x.strip().lower()) for x in include_domains):
            return _err("VALIDATION_ERROR", "include_domains contains a malformed domain/host", field="include_domains")
        include_domains = [x.strip().lower() for x in include_domains if x.strip()]
    if exclude_domains is not None:
        if not isinstance(exclude_domains, list) or any(not isinstance(x, str) for x in exclude_domains):
            return _err("VALIDATION_ERROR", "exclude_domains must be an array of strings", field="exclude_domains")
        if any(not _valid_host(x.strip().lower()) for x in exclude_domains):
            return _err("VALIDATION_ERROR", "exclude_domains contains a malformed domain/host", field="exclude_domains")
        exclude_domains = [x.strip().lower() for x in exclude_domains if x.strip()]

    for bfield, bval in (("include_answer", include_answer), ("include_raw_content", include_raw_content), ("include_images", include_images)):
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bfield} must be a boolean", field=bfield)

    if time_range is not None and time_range not in ("day", "week", "month", "year"):
        return _err("VALIDATION_ERROR", "time_range must be one of: day, week, month, year", field="time_range")

    try:
        sd = _parse_dt(start_date, "start_date")
        ed = _parse_dt(end_date, "end_date")
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e))
    if sd and ed and sd > ed:
        return _err("VALIDATION_ERROR", "start_date must be <= end_date", field="start_date")

    if idempotency_key is not None and not isinstance(idempotency_key, str):
        return _err("VALIDATION_ERROR", "idempotency_key must be a string", field="idempotency_key")

    tool = "tavily-search"
    input_obj = {
        "query": query,
        "search_depth": search_depth,
        "max_results": max_results,
        "include_domains": include_domains,
        "exclude_domains": exclude_domains,
        "include_answer": include_answer,
        "include_raw_content": include_raw_content,
        "include_images": include_images,
        "time_range": time_range,
        "start_date": start_date,
        "end_date": end_date,
    }

    # ---- Load store ----
    api_keys = _load("api_keys.json")
    requests_rows = _load("requests.json")
    web_resources = _load("web_resources.json")
    request_results = _load("request_results.json")

    # ---- Resolve ambient key that can serve this call ----
    api_key = _find_working_key(api_keys, tool)
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this operation")

    _reset_month_if_needed(api_key)

    # ---- Idempotency ----
    if idempotency_key is not None:
        for r in requests_rows:
            if r.get("api_key_id") == api_key["id"] and r.get("tool") == tool and r.get("idempotency_key") == idempotency_key:
                # log this call as its own dynamics? Real APIs typically don't create a new request row on idempotent hit.
                # We still must "record itself" via requests collection; but business rule says idempotency returns existing and does not create new requests row.
                # So we treat existing row as the record and update its updated_at/last_used_at without double charging.
                r["updated_at"] = now_iso
                api_key["last_used_at"] = now_iso
                api_key["updated_at"] = now_iso
                _save("requests.json", requests_rows)
                _save("api_keys.json", api_keys)
                return (r.get("response") if isinstance(r.get("response"), dict) else {"results": [], "query": query})

    # ---- Authorization rules (status/allowed_tools) ----
    if api_key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")
    allowed = api_key.get("allowed_tools")
    if isinstance(allowed, list) and len(allowed) > 0 and tool not in allowed:
        return _err("UNAUTHORIZED", "API key is not allowed to use this tool")

    # ---- Quota / Rate limit ----
    normalized_target = query.strip()
    started_at = now_iso

    # Estimate tokens based on desired max_results (upper bound)
    est_tokens = _estimate_tokens(input_obj, int(max_results))

    rate_ok = _enforce_rate_limit(api_key["id"], api_key, requests_rows, tool)
    quota_ok = _quota_allows(api_key, add_requests=1, add_tokens=est_tokens)
    if not rate_ok or not quota_ok:
        # create failed request row with 429, increment usage_requests by 1 (excluding auth failures)
        resp = {
            "query": query,
            "results": [],
            "answer": None,
            "images": [] if include_images else None,
        }
        err_msg = "Rate limit exceeded" if not rate_ok else "Quota exceeded"
        err_code = "RATE_LIMIT" if not rate_ok else "QUOTA_EXCEEDED"
        finished_at = now_iso
        req_row = _log_request(
            requests_rows, api_key["id"], tool, "failed", 429, idempotency_key, input_obj, normalized_target,
            resp, err_code, err_msg, 0, 0, started_at, finished_at
        )
        api_key["usage_requests"] = int(api_key.get("usage_requests", 0)) + 1
        api_key["updated_at"] = now_iso
        _save("requests.json", requests_rows)
        _save("api_keys.json", api_keys)
        latency_ms = int((time.time() - t0) * 1000)
        resp_meta = {"request_id": req_row["id"], "status": "failed", "http_status": 429, "latency_ms": latency_ms}
        resp["meta"] = resp_meta
        return _err(err_code, err_msg, http_status=429, request_id=req_row["id"])

    # ---- Execute "search" over local datastore as backend index ----
    # Candidate web_resources: match query terms against title/description/content_text/host/url
    q = query.strip().lower()
    terms = [t for t in "".join(ch if (ch.isalnum() or ch.isspace()) else " " for ch in q).split() if t]
    if not terms:
        terms = [q]

    inc = set(include_domains or [])
    exc = set(exclude_domains or [])

    # time filters use fetched_at when available, else first_seen_at
    def _dt_from_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    # compute time_range window
    tr_start = None
    if time_range:
        delta = {"day": 1, "week": 7, "month": 30, "year": 365}[time_range]
        tr_start = now - datetime.timedelta(days=delta)

    scored = []
    for w in web_resources:
        host = (w.get("host") or "").lower()
        if inc and host not in inc:
            continue
        if exc and host in exc:
            continue
        # date constraints
        wdt = _dt_from_iso(w.get("fetched_at")) or _dt_from_iso(w.get("first_seen_at")) or _dt_from_iso(w.get("created_at"))
        if sd and wdt and wdt < sd:
            continue
        if ed and wdt and wdt > ed:
            continue
        if tr_start and wdt and wdt < tr_start:
            continue

        blob = " ".join([
            str(w.get("title") or ""),
            str(w.get("description") or ""),
            str(w.get("content_text") or ""),
            str(w.get("canonical_url") or ""),
            host
        ]).lower()
        hits = 0
        for t in terms:
            if t and t in blob:
                hits += 1
        if hits == 0:
            continue
        # score: more hits + fetched recency bump
        rec = 0.0
        if wdt:
            age_days = max(0.0, (now - wdt).total_seconds() / 86400.0)
            rec = 1.0 / (1.0 + age_days)
        score = hits * 10.0 + rec
        scored.append((score, w))

    scored.sort(key=lambda x: (-x[0], (x[1].get("fetched_at") or ""), x[1].get("canonical_url") or ""))

    results = []
    n = 0
    for score, w in scored:
        if n >= max_results:
            break
        item = {
            "url": w.get("canonical_url"),
            "title": w.get("title"),
            "content": (w.get("content_text") if include_raw_content else None),
            "snippet": w.get("description"),
            "score": score,
        }
        results.append(item)
        n += 1

    # If insufficient results, synthesize deterministic placeholder URLs tied to query and persist them
    while len(results) < max_results:
        idx = len(results) + 1
        slug = "-".join(terms[:6]) or "query"
        gen_url = f"https://example.com/search/{slug}?r={idx}"
        try:
            canon, uh, host = _normalize_url(gen_url)
        except ValueError:
            break
        wr, _ = _upsert_web_resource(web_resources, canon, uh, host, title=f"{query} (result {idx})", description=f"Synthesized result for '{query}'", content_text=(f"Generated content for {query}" if include_raw_content else None))
        results.append({
            "url": wr.get("canonical_url"),
            "title": wr.get("title"),
            "content": (wr.get("content_text") if include_raw_content else None),
            "snippet": wr.get("description"),
            "score": 1.0,
        })

    # images: from metadata if present, else none
    images = []
    if include_images:
        for r in results[:max_results]:
            images.append({"source_url": r.get("url"), "image_url": None, "alt": None})

    answer = None
    if include_answer:
        tops = [r.get("title") for r in results[:3] if r.get("title")]
        answer = f"Top results for '{query}': " + "; ".join(tops) if tops else f"No strong matches found for '{query}'."

    # ---- Create request row & results rows, increment usage atomically with finalization ----
    # tokens used based on actual result count
    tokens_used = _estimate_tokens(input_obj, len(results))
    finished_at = now_iso

    response_obj = {"query": query, "results": results, "answer": answer}
    if include_images:
        response_obj["images"] = images

    req_row = _log_request(
        requests_rows, api_key["id"], tool, "succeeded", 200, idempotency_key, input_obj,
        normalized_target, response_obj, None, None, tokens_used, len(results), started_at, finished_at
    )

    # persist each returned URL and request_results
    rank = 1
    for item in results:
        url = item.get("url")
        if not isinstance(url, str) or not url:
            continue
        try:
            canon, uh, host = _normalize_url(url)
        except ValueError:
            continue
        wr, _ = _upsert_web_resource(web_resources, canon, uh, host, title=item.get("title"), description=item.get("snippet"))
        _ensure_request_result(
            request_results, req_row["id"], wr["id"], "search_hit",
            rank=rank, score=item.get("score"),
            metadata={"query": query, "search_depth": (search_depth or "basic")}
        )
        rank += 1

    # charge usage (requests + tokens) once
    _charge_usage(api_key, tokens_used)

    # save all
    _save("web_resources.json", web_resources)
    _save("request_results.json", request_results)
    _save("requests.json", requests_rows)
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    response_obj["meta"] = {"request_id": req_row["id"], "status": "succeeded", "http_status": 200, "latency_ms": latency_ms}
    return response_obj

def tavily_extract(urls, include_images=None, include_raw_content=None, extract_depth=None, idempotency_key=None, **_extra):
    import json, os, datetime
    import time, hashlib, uuid
    from urllib.parse import urlparse, urlunparse, parse_qsl, urlencode

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0424000" if __import__("os").path.isdir("./environment_mix/0424000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _valid_host(h):
        if not isinstance(h, str) or not h:
            return False
        hh = h.strip().lower()
        if len(hh) > 253:
            return False
        for ch in hh:
            if not (ch.isalnum() or ch in ".-"):
                return False
        if ".." in hh or hh.startswith("-") or hh.endswith("-") or hh.startswith(".") or hh.endswith("."):
            return False
        return True

    def _normalize_url(url):
        if not isinstance(url, str) or not url.strip():
            raise ValueError("url must be a non-empty string")
        u = url.strip()
        p = urlparse(u)
        if p.scheme not in ("http", "https"):
            raise ValueError("url must be http(s)")
        if not p.netloc:
            raise ValueError("url must include a host")
        host = p.hostname.lower() if p.hostname else ""
        if not _valid_host(host):
            raise ValueError("url host is malformed")
        netloc = host
        if p.port and not ((p.scheme == "http" and p.port == 80) or (p.scheme == "https" and p.port == 443)):
            netloc = f"{host}:{p.port}"
        path = p.path or "/"
        while "//" in path:
            path = path.replace("//", "/")
        q = urlencode(sorted(parse_qsl(p.query, keep_blank_values=True)))
        canon = urlunparse((p.scheme.lower(), netloc, path, "", q, ""))  # strip fragment
        url_hash = hashlib.sha256(canon.encode("utf-8")).hexdigest()
        return canon, url_hash, host

    def _log_request(requests_rows, api_key_id, tool, status, http_status, idempotency_key, input_obj, normalized_target, response_obj, error_code, error_message, tokens_used, result_count, started_at, finished_at):
        rid = _new_id("req")
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool": tool,
            "status": status,
            "idempotency_key": idempotency_key,
            "input": input_obj,
            "normalized_target": normalized_target,
            "response": response_obj,
            "error_code": error_code,
            "error_message": error_message,
            "http_status": http_status,
            "tokens_used": int(tokens_used),
            "result_count": result_count,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        requests_rows.append(row)
        return row

    def _find_working_key(api_keys_rows, tool):
        for k in api_keys_rows:
            if k.get("status") != "active":
                continue
            allowed = k.get("allowed_tools")
            if isinstance(allowed, list) and len(allowed) > 0 and tool not in allowed:
                continue
            if not isinstance(k.get("rate_limit_rpm"), int) or k["rate_limit_rpm"] < 1:
                continue
            if not isinstance(k.get("monthly_request_quota"), int) or k["monthly_request_quota"] < 0:
                continue
            if not isinstance(k.get("monthly_token_quota"), int) or k["monthly_token_quota"] < 0:
                continue
            if not isinstance(k.get("usage_requests"), int) or k["usage_requests"] < 0:
                continue
            if not isinstance(k.get("usage_tokens"), int) or k["usage_tokens"] < 0:
                continue
            if not isinstance(k.get("usage_month"), str) or len(k["usage_month"]) != 7:
                continue
            return k
        return None

    def _reset_month_if_needed(k):
        month = now.strftime("%Y-%m")
        if k.get("usage_month") != month:
            k["usage_month"] = month
            k["usage_requests"] = 0
            k["usage_tokens"] = 0

    def _enforce_rate_limit(api_key_id, api_key_row, requests_rows):
        rpm = api_key_row.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1:
            return False
        window_start = (now - datetime.timedelta(seconds=60)).isoformat()
        cnt = 0
        for r in requests_rows:
            if r.get("api_key_id") != api_key_id:
                continue
            ca = r.get("created_at")
            if isinstance(ca, str) and ca >= window_start:
                cnt += 1
        return cnt < rpm

    def _quota_allows(api_key_row, add_requests=1, add_tokens=0):
        mrq = api_key_row.get("monthly_request_quota", 0)
        mtq = api_key_row.get("monthly_token_quota", 0)
        ur = api_key_row.get("usage_requests", 0)
        ut = api_key_row.get("usage_tokens", 0)
        if not isinstance(mrq, int) or not isinstance(mtq, int) or not isinstance(ur, int) or not isinstance(ut, int):
            return False
        if mrq > 0 and ur + add_requests > mrq:
            return False
        if mtq > 0 and ut + add_tokens > mtq:
            return False
        return True

    def _charge_usage(api_key_row, tokens_used):
        api_key_row["usage_requests"] = int(api_key_row.get("usage_requests", 0)) + 1
        api_key_row["usage_tokens"] = int(api_key_row.get("usage_tokens", 0)) + int(tokens_used)
        api_key_row["last_used_at"] = now_iso
        api_key_row["updated_at"] = now_iso

    def _estimate_tokens(inp, n_urls):
        base = 25
        depth = inp.get("extract_depth") or "basic"
        depth_mul = 2 if depth == "advanced" else 1
        raw = 12 if inp.get("include_raw_content") else 0
        imgs = 6 if inp.get("include_images") else 0
        return int((base + n_urls * (12 + raw + imgs)) * depth_mul)

    def _upsert_web_resource(web_resources_rows, canonical_url, url_hash, host):
        existing = None
        for w in web_resources_rows:
            if w.get("url_hash") == url_hash:
                existing = w
                break
        if existing is None:
            wid = _new_id("wr")
            row = {
                "id": wid,
                "canonical_url": canonical_url,
                "url_hash": url_hash,
                "host": host,
                "title": None,
                "description": None,
                "content_text": None,
                "content_html": None,
                "content_storage_url": None,
                "content_mime_type": None,
                "http_status_last": None,
                "fetched_at": None,
                "first_seen_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
                "status": "discovered",
            }
            web_resources_rows.append(row)
            return row, True
        existing["canonical_url"] = canonical_url
        existing["host"] = host
        existing["updated_at"] = now_iso
        return existing, False

    def _set_web_resource_fetch_state(w, ok, content_text=None, content_html=None, title=None, description=None, mime_type="text/html"):
        # lifecycle transitions allowed broadly; set status accordingly
        w["http_status_last"] = 200 if ok else 502
        w["fetched_at"] = now_iso
        if ok:
            w["status"] = "fetched"
            if title is not None:
                w["title"] = title
            if description is not None:
                w["description"] = description
            if content_text is not None:
                w["content_text"] = content_text
            if content_html is not None:
                w["content_html"] = content_html
            w["content_mime_type"] = mime_type
        else:
            w["status"] = "fetch_failed"
        w["updated_at"] = now_iso

    def _ensure_request_result(request_results_rows, request_id, web_resource_id, result_type, metadata):
        existing = None
        for rr in request_results_rows:
            if rr.get("request_id") == request_id and rr.get("web_resource_id") == web_resource_id and rr.get("result_type") == result_type:
                existing = rr
                break
        if existing is None:
            rrid = _new_id("rr")
            row = {
                "id": rrid,
                "request_id": request_id,
                "web_resource_id": web_resource_id,
                "result_type": result_type,
                "rank": None,
                "score": None,
                "source_url_id": None,
                "depth": None,
                "anchor_text": None,
                "metadata": metadata if isinstance(metadata, dict) else {},
                "created_at": now_iso,
                "updated_at": now_iso,
                "status": "active",
            }
            request_results_rows.append(row)
            return row, True
        if isinstance(metadata, dict):
            m = existing.get("metadata")
            if not isinstance(m, dict):
                m = {}
            m.update(metadata)
            existing["metadata"] = m
        existing["updated_at"] = now_iso
        return existing, False

    # ---- Validate inputs ----
    if not isinstance(urls, list) or len(urls) < 1:
        return _err("VALIDATION_ERROR", "urls is required and must be a non-empty array", field="urls")
    if any(not isinstance(u, str) for u in urls):
        return _err("VALIDATION_ERROR", "urls must be an array of strings", field="urls")

    for bfield, bval in (("include_images", include_images), ("include_raw_content", include_raw_content)):
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bfield} must be a boolean", field=bfield)

    if extract_depth is not None and extract_depth not in ("basic", "advanced"):
        return _err("VALIDATION_ERROR", "extract_depth must be one of: basic, advanced", field="extract_depth")

    if idempotency_key is not None and not isinstance(idempotency_key, str):
        return _err("VALIDATION_ERROR", "idempotency_key must be a string", field="idempotency_key")

    # Validate each url parses
    normalized_list = []
    try:
        for u in urls:
            canon, uh, host = _normalize_url(u)
            normalized_list.append((u, canon, uh, host))
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e), field="urls")

    tool = "tavily-extract"
    input_obj = {
        "urls": urls,
        "include_images": include_images,
        "include_raw_content": include_raw_content,
        "extract_depth": extract_depth,
    }

    # ---- Load store ----
    api_keys = _load("api_keys.json")
    requests_rows = _load("requests.json")
    web_resources = _load("web_resources.json")
    request_results = _load("request_results.json")

    # ---- Resolve ambient key ----
    api_key = _find_working_key(api_keys, tool)
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available for this operation")

    _reset_month_if_needed(api_key)

    # ---- Idempotency ----
    if idempotency_key is not None:
        for r in requests_rows:
            if r.get("api_key_id") == api_key["id"] and r.get("tool") == tool and r.get("idempotency_key") == idempotency_key:
                r["updated_at"] = now_iso
                api_key["last_used_at"] = now_iso
                api_key["updated_at"] = now_iso
                _save("requests.json", requests_rows)
                _save("api_keys.json", api_keys)
                return (r.get("response") if isinstance(r.get("response"), dict) else {"results": []})

    # ---- Authorization rules ----
    if api_key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")
    allowed = api_key.get("allowed_tools")
    if isinstance(allowed, list) and len(allowed) > 0 and tool not in allowed:
        return _err("UNAUTHORIZED", "API key is not allowed to use this tool")

    # ---- Quota / Rate limit ----
    started_at = now_iso
    normalized_target = normalized_list[0][1] if normalized_list else None
    est_tokens = _estimate_tokens(input_obj, len(urls))

    rate_ok = _enforce_rate_limit(api_key["id"], api_key, requests_rows)
    quota_ok = _quota_allows(api_key, add_requests=1, add_tokens=est_tokens)
    if not rate_ok or not quota_ok:
        resp = {"results": []}
        err_msg = "Rate limit exceeded" if not rate_ok else "Quota exceeded"
        err_code = "RATE_LIMIT" if not rate_ok else "QUOTA_EXCEEDED"
        finished_at = now_iso
        req_row = _log_request(
            requests_rows, api_key["id"], tool, "failed", 429, idempotency_key, input_obj,
            normalized_target, resp, err_code, err_msg, 0, 0, started_at, finished_at
        )
        api_key["usage_requests"] = int(api_key.get("usage_requests", 0)) + 1
        api_key["updated_at"] = now_iso
        _save("requests.json", requests_rows)
        _save("api_keys.json", api_keys)
        return _err(err_code, err_msg, http_status=429, request_id=req_row["id"])

    # ---- Execute "extract" locally: mark fetched if resource exists; otherwise deterministic placeholder content ----
    per_url = []
    ok_count = 0

    for original, canon, uh, host in normalized_list:
        wr, _ = _upsert_web_resource(web_resources, canon, uh, host)

        # Simulated fetch: if existing content_text/html already present treat as success; else create placeholder content.
        already_has = isinstance(wr.get("content_text"), str) and wr.get("content_text")
        ok = True
        content_text = wr.get("content_text") if already_has else f"Extracted content for {canon}"
        content_html = wr.get("content_html") if already_has else (f"<html><head><title>{canon}</title></head><body><p>{content_text}</p></body></html>" if include_raw_content else None)
        title = wr.get("title") or f"{host}"
        description = wr.get("description") or f"Extracted from {host}"
        _set_web_resource_fetch_state(
            wr, ok,
            content_text=(content_text if include_raw_content else None),
            content_html=(content_html if include_raw_content else None),
            title=title,
            description=description,
            mime_type="text/html"
        )

        meta = {"extract_depth": (extract_depth or "basic")}
        _ensure_request_result(request_results, None, None, "extracted", {})  # placeholder to avoid lint (will be replaced)
        per_url.append({
            "url": canon,
            "title": wr.get("title"),
            "content": (wr.get("content_text") if include_raw_content else None),
            "raw_content": (wr.get("content_html") if include_raw_content else None),
            "status": "success" if ok else "failed",
            "http_status": wr.get("http_status_last"),
            "images": ([{"image_url": None, "alt": None}] if include_images else None),
        })
        ok_count += 1 if ok else 0

    # Create request row now (need request_id for request_results)
    tokens_used = _estimate_tokens(input_obj, len(urls))
    finished_at = now_iso

    response_obj = {"results": per_url}
    req_row = _log_request(
        requests_rows, api_key["id"], tool, "succeeded", 200, idempotency_key, input_obj,
        normalized_target, response_obj, None, None, tokens_used, len(per_url), started_at, finished_at
    )

    # Fixup: create request_results rows for extracted items (unique enforced)
    # (Also remove the placeholder no-op insert attempt above by not saving that artifact; we didn't append because it used None ids.)
    # Ensure no invalid rows were added:
    request_results = [rr for rr in request_results if rr.get("request_id") and rr.get("web_resource_id") and rr.get("result_type")]

    for original, canon, uh, host in normalized_list:
        # locate wr again
        wr = None
        for w in web_resources:
            if w.get("url_hash") == uh:
                wr = w
                break
        if wr is None:
            continue
        _ensure_request_result(
            request_results, req_row["id"], wr["id"], "extracted",
            metadata={"url": canon, "extract_depth": (extract_depth or "basic")}
        )

    _charge_usage(api_key, tokens_used)

    _save("web_resources.json", web_resources)
    _save("request_results.json", request_results)
    _save("requests.json", requests_rows)
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    response_obj["meta"] = {"request_id": req_row["id"], "status": "succeeded", "http_status": 200, "latency_ms": latency_ms}
    return response_obj

def tavily_map(url, max_depth=None, max_pages=None, allowed_path_prefixes=None, blocked_path_prefixes=None, same_host_only=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, hashlib, secrets
    from urllib.parse import urlsplit, urlunsplit

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0424000" if __import__("os").path.isdir("./environment_mix/0424000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool = "tavily-map"

    def _utc_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _month_key(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        dt = dt.astimezone(datetime.timezone.utc)
        return f"{dt.year:04d}-{dt.month:02d}"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        # match existing style prefixes in datastore (tav_req_, tav_url_) while keeping uniqueness
        return f"{prefix}_{secrets.token_hex(12)}"

    def _normalize_url(u):
        if not isinstance(u, str) or not u.strip():
            return None, None, None
        u = u.strip()
        try:
            parts = urlsplit(u)
        except Exception:
            return None, None, None
        scheme = (parts.scheme or "").lower()
        if scheme not in ("http", "https"):
            return None, None, None
        if not parts.netloc:
            return None, None, None
        host = (parts.hostname or "").lower()
        if not host:
            return None, None, None
        port = parts.port
        netloc = host
        if port and not ((scheme == "http" and port == 80) or (scheme == "https" and port == 443)):
            netloc = f"{host}:{port}"
        # normalize path: ensure leading slash, collapse empty
        path = parts.path or "/"
        if not path.startswith("/"):
            path = "/" + path
        # drop fragment; keep query (mapping base should keep query if provided, but canonicalization commonly keeps it)
        # Deterministic: keep query as-is; drop fragment.
        canonical = urlunsplit((scheme, netloc, path, parts.query or "", ""))
        url_hash = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
        return canonical, url_hash, host

    def _safe_jsonable(obj, _depth=0, _seen=None):
        # prevent circular refs / non-serializable in stored request.input/response
        if _seen is None:
            _seen = set()
        if _depth > 6:
            return None
        oid = id(obj)
        if oid in _seen:
            return None
        if obj is None or isinstance(obj, (str, int, float, bool)):
            return obj
        if isinstance(obj, list):
            _seen.add(oid)
            return [_safe_jsonable(x, _depth + 1, _seen) for x in obj]
        if isinstance(obj, dict):
            _seen.add(oid)
            out = {}
            for k, v in obj.items():
                if isinstance(k, str):
                    out[k] = _safe_jsonable(v, _depth + 1, _seen)
            return out
        return str(obj)

    # Validate inputs
    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url must be a non-empty string")
    if max_depth is not None and (not isinstance(max_depth, int) or max_depth < 0):
        return _err("VALIDATION_ERROR", "max_depth must be an integer >= 0")
    if max_pages is not None and (not isinstance(max_pages, int) or max_pages < 1):
        return _err("VALIDATION_ERROR", "max_pages must be an integer >= 1")
    if allowed_path_prefixes is not None:
        if not isinstance(allowed_path_prefixes, list) or any(not isinstance(x, str) for x in allowed_path_prefixes):
            return _err("VALIDATION_ERROR", "allowed_path_prefixes must be an array of strings")
    if blocked_path_prefixes is not None:
        if not isinstance(blocked_path_prefixes, list) or any(not isinstance(x, str) for x in blocked_path_prefixes):
            return _err("VALIDATION_ERROR", "blocked_path_prefixes must be an array of strings")
    if same_host_only is not None and not isinstance(same_host_only, bool):
        return _err("VALIDATION_ERROR", "same_host_only must be a boolean")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")

    canonical_url, url_hash, host = _normalize_url(url)
    if not canonical_url:
        return _err("VALIDATION_ERROR", "url must be a valid http(s) URI")

    # Ambient authentication: pick an active key that allows this tool and can serve quotas.
    api_keys = _load("api_keys.json")
    requests_rows = _load("requests.json")
    web_resources = _load("web_resources.json")
    request_results = _load("request_results.json")
    crawl_jobs = _load("crawl_jobs.json")

    now = _utc_now()
    now_iso = _iso(now)
    this_month = _month_key(now)

    # Find a usable active key that allows this tool
    key_row = None
    for k in api_keys:
        if k.get("status") != "active":
            continue
        allowed = k.get("allowed_tools")
        if isinstance(allowed, list) and len(allowed) > 0 and tool not in allowed:
            continue
        # rate_limit_rpm must be within schema but enforce sensible
        rpm = k.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1:
            continue
        key_row = k
        break

    if key_row is None:
        return _err("UNAUTHORIZED", "No active API key available to serve this request")

    api_key_id = key_row.get("id")

    # Idempotency: if exists, return stored response without creating a new request row
    if idempotency_key is not None:
        for r in requests_rows:
            if r.get("api_key_id") == api_key_id and r.get("tool") == tool and r.get("idempotency_key") == idempotency_key:
                # update last_used_at (successful read of idempotent cached response)
                for k in api_keys:
                    if k.get("id") == api_key_id:
                        k["last_used_at"] = now_iso
                        k["updated_at"] = now_iso
                        _save("api_keys.json", api_keys)
                        break
                resp = r.get("response")
                return resp if isinstance(resp, dict) else {"request_id": r.get("id"), "status": r.get("status")}

    # Enforce lifecycle/tool rules prior to creating requests row? Business rule says: if key not active reject and must not create request.
    # For quotas/rate-limit: create a failed requests row with 429 and do not perform external work.
    # We'll treat "external work" here as creating crawl_job + outputs; for 429 we only create request row failed.
    # We must increment usage_requests by 1 on success/failure (excluding auth failures).
    # Also enforce monthly window resetting.
    def _reset_month_if_needed(k):
        um = k.get("usage_month")
        if um != this_month:
            k["usage_month"] = this_month
            k["usage_requests"] = 0
            k["usage_tokens"] = 0

    # Rate limit rpm: count requests in last 60s for this key in requests collection
    def _count_last_minute(api_key_id_):
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for r in requests_rows:
            if r.get("api_key_id") != api_key_id_:
                continue
            dt = _parse_iso(r.get("created_at"))
            if dt and dt >= cutoff:
                c += 1
        return c

    # Apply month reset and quota checks on the chosen key row
    for k in api_keys:
        if k.get("id") == api_key_id:
            _reset_month_if_needed(k)
            key_row = k
            break

    rpm = int(key_row.get("rate_limit_rpm") or 0)
    req_quota = int(key_row.get("monthly_request_quota") or 0)
    tok_quota = int(key_row.get("monthly_token_quota") or 0)

    limited = False
    limit_reason = None
    if rpm > 0 and _count_last_minute(api_key_id) >= rpm:
        limited = True
        limit_reason = "rate_limited"
    if not limited and req_quota > 0 and int(key_row.get("usage_requests") or 0) >= req_quota:
        limited = True
        limit_reason = "request_quota_exceeded"
    if not limited and tok_quota > 0 and int(key_row.get("usage_tokens") or 0) >= tok_quota:
        limited = True
        limit_reason = "token_quota_exceeded"

    # Create requests row (exactly one) for this tool invocation (even if limited -> failed row)
    req_id = _new_id("tav_req")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool": tool,
        "status": "queued",
        "idempotency_key": idempotency_key,
        "input": _safe_jsonable({
            "url": canonical_url,
            "max_depth": max_depth,
            "max_pages": max_pages,
            "allowed_path_prefixes": allowed_path_prefixes,
            "blocked_path_prefixes": blocked_path_prefixes,
            "same_host_only": same_host_only
        }),
        "normalized_target": canonical_url,
        "response": None,
        "error_code": None,
        "error_message": None,
        "http_status": None,
        "tokens_used": 0,
        "result_count": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # Helper for request status transition enforcement
    transitions = {
        "queued": ["running", "cancelled", "failed"],
        "running": ["succeeded", "failed", "cancelled"],
        "succeeded": [],
        "failed": [],
        "cancelled": []
    }
    def _set_req_status(row, new_status, http_status=None, error_code=None, error_message=None):
        cur = row.get("status")
        if new_status == cur:
            return True
        if cur not in transitions or new_status not in transitions[cur]:
            return False
        row["status"] = new_status
        row["updated_at"] = now_iso
        if new_status in ("running",) and row.get("started_at") is None:
            row["started_at"] = now_iso
        if new_status in ("succeeded", "failed", "cancelled"):
            row["finished_at"] = now_iso
        if http_status is not None:
            row["http_status"] = int(http_status)
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        return True

    # If limited -> immediately fail request with 429, increment usage_requests (not tokens), persist and return response.
    if limited:
        if not _set_req_status(req_row, "failed", http_status=429, error_code=limit_reason,
                               error_message="Rate limit or quota exceeded for this API key. Try again later."):
            return _err("INVALID_TRANSITION", "Illegal request status transition")
        # finalize response body
        resp_body = {
            "request_id": req_id,
            "status": req_row["status"],
            "error": {
                "code": req_row["error_code"],
                "message": req_row["error_message"]
            }
        }
        req_row["response"] = _safe_jsonable(resp_body)
        req_row["result_count"] = 0

        requests_rows.append(req_row)

        # increment usage_requests (excluding auth failures)
        for k in api_keys:
            if k.get("id") == api_key_id:
                k["usage_requests"] = int(k.get("usage_requests") or 0) + 1
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break

        _save("requests.json", requests_rows)
        _save("api_keys.json", api_keys)

        return resp_body

    # Proceed with creating job (no external fetch; simulate async mapping with minimal seed)
    if not _set_req_status(req_row, "running"):
        return _err("INVALID_TRANSITION", "Illegal request status transition")
    req_row["started_at"] = req_row.get("started_at") or now_iso

    # Upsert base web_resource
    wr = None
    for x in web_resources:
        if x.get("url_hash") == url_hash:
            wr = x
            break
    if wr is None:
        wr_id = _new_id("tav_url")
        wr = {
            "id": wr_id,
            "canonical_url": canonical_url,
            "url_hash": url_hash,
            "host": host,
            "title": None,
            "description": None,
            "content_text": None,
            "content_html": None,
            "content_storage_url": None,
            "content_mime_type": None,
            "http_status_last": None,
            "fetched_at": None,
            "first_seen_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
            "status": "discovered"
        }
        web_resources.append(wr)
    else:
        wr["updated_at"] = now_iso
        if not wr.get("first_seen_at"):
            wr["first_seen_at"] = now_iso

    base_web_resource_id = wr.get("id")

    # Create crawl_job unique(request_id)
    # If one exists already (shouldn't for new request), enforce uniqueness
    for j in crawl_jobs:
        if j.get("request_id") == req_id:
            return _err("CONFLICT", "Crawl job already exists for this request")

    job_id = _new_id("crawljob")
    job_row = {
        "id": job_id,
        "request_id": req_id,
        "mode": "map",
        "status": req_row["status"],
        "base_web_resource_id": base_web_resource_id,
        "max_depth": max_depth,
        "max_pages": max_pages,
        "allowed_path_prefixes": allowed_path_prefixes,
        "blocked_path_prefixes": blocked_path_prefixes,
        "same_host_only": bool(same_host_only) if same_host_only is not None else True,
        "fetch_content": False,
        "pages_discovered": 1,
        "pages_fetched": 0,
        "started_at": req_row.get("started_at"),
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    crawl_jobs.append(job_row)

    # Create request_results for base URL (mapped_url), enforcing uniqueness
    def _find_rr(request_id, web_resource_id, result_type):
        for rr in request_results:
            if rr.get("request_id") == request_id and rr.get("web_resource_id") == web_resource_id and rr.get("result_type") == result_type:
                return rr
        return None

    rr = _find_rr(req_id, base_web_resource_id, "mapped_url")
    if rr is None:
        rr_row = {
            "id": _new_id("tav_rr"),
            "request_id": req_id,
            "web_resource_id": base_web_resource_id,
            "result_type": "mapped_url",
            "rank": 1,
            "score": None,
            "source_url_id": None,
            "depth": 0,
            "anchor_text": None,
            "metadata": {"seed": True},
            "created_at": now_iso,
            "updated_at": now_iso,
            "status": "active"
        }
        request_results.append(rr_row)
    else:
        # keep best (lowest) rank and shortest depth
        if rr.get("rank") is None or rr.get("rank") > 1:
            rr["rank"] = 1
        if rr.get("depth") is None or rr.get("depth") > 0:
            rr["depth"] = 0
        rr["updated_at"] = now_iso
        md = rr.get("metadata") if isinstance(rr.get("metadata"), dict) else {}
        md["seed"] = True
        rr["metadata"] = md

    # Finalize request as succeeded with minimal response (async job)
    # Token accounting: record tokens_used and increment usage_tokens atomically with request finalization.
    tokens_used = 1  # minimal compute unit for job enqueue
    req_row["tokens_used"] = tokens_used
    req_row["result_count"] = 1

    if not _set_req_status(req_row, "succeeded", http_status=200):
        return _err("INVALID_TRANSITION", "Illegal request status transition")

    resp_body = {
        "request_id": req_id,
        "status": req_row["status"],
        "job": {
            "id": job_id,
            "mode": job_row["mode"],
            "status": job_row["status"],
            "base_web_resource_id": base_web_resource_id,
            "max_depth": job_row["max_depth"],
            "max_pages": job_row["max_pages"],
            "same_host_only": job_row["same_host_only"],
            "fetch_content": job_row["fetch_content"],
            "pages_discovered": job_row["pages_discovered"],
            "pages_fetched": job_row["pages_fetched"],
            "created_at": job_row["created_at"],
            "updated_at": job_row["updated_at"]
        }
    }
    req_row["response"] = _safe_jsonable(resp_body)

    # Persist mutations
    requests_rows.append(req_row)

    # Update job status to mirror request (rule)
    job_row["status"] = req_row["status"]
    job_row["updated_at"] = now_iso
    job_row["finished_at"] = req_row.get("finished_at")

    # Increment usage_requests and usage_tokens (excluding auth failures). Also set last_used.
    for k in api_keys:
        if k.get("id") == api_key_id:
            k["usage_requests"] = int(k.get("usage_requests") or 0) + 1
            k["usage_tokens"] = int(k.get("usage_tokens") or 0) + int(tokens_used)
            # enforce quota constraints after increment: if it exceeds, clamp and mark conflict? Real backend would prevent earlier.
            # We already checked before; keep non-negative.
            if k["usage_requests"] < 0:
                k["usage_requests"] = 0
            if k["usage_tokens"] < 0:
                k["usage_tokens"] = 0
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break

    _save("web_resources.json", web_resources)
    _save("request_results.json", request_results)
    _save("crawl_jobs.json", crawl_jobs)
    _save("requests.json", requests_rows)
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    resp_body["meta"] = {"latency_ms": latency_ms}
    return resp_body

def tavily_requests_list(api_key, tool=None, status=None, idempotency_key=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, hashlib, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0424000" if __import__("os").path.isdir("./environment_mix/0424000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    allowed_tools = {"tavily-search", "tavily-extract", "tavily-crawl", "tavily-map"}
    if tool is not None and (not isinstance(tool, str) or tool not in allowed_tools):
        return _err("VALIDATION_ERROR", "tool must be one of: tavily-search, tavily-extract, tavily-crawl, tavily-map")
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")

    ca = _parse_dt(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        return ca
    cb = _parse_dt(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        return cb
    if ca and cb and ca > cb:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    api_keys = _load("api_keys.json")
    reqs = _load("requests.json")

    presented = api_key.strip()
    presented_sha = hashlib.sha256(presented.encode("utf-8")).hexdigest()
    key_row = None
    for r in api_keys:
        if r.get("id") == presented or r.get("key_hash") == presented_sha:
            key_row = r
            break
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", reason="FORBIDDEN")

    # Optional: permission to access request history. Use allowed_tools empty/all or non-empty; request history is allowed if key can call any tool.
    # If allowed_tools is explicitly empty meaning all tools, allow. If it's a list but empty -> all. If it's missing, allow.
    if "allowed_tools" in key_row and isinstance(key_row.get("allowed_tools"), list):
        pass

    # Cursor handling: base64("created_at|id") for the last item of previous page.
    cursor_created_at = None
    cursor_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            parts = raw.decode("utf-8").split("|", 1)
            if len(parts) != 2:
                return _err("VALIDATION_ERROR", "cursor is invalid")
            cursor_created_at, cursor_id = parts[0], parts[1]
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")

    def _dt_from_row(s):
        if not s or not isinstance(s, str):
            return None
        ss = s
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    # Filter to this api_key_id and optional filters
    key_id = key_row.get("id")
    filtered = []
    for r in reqs:
        if r.get("api_key_id") != key_id:
            continue
        if tool is not None and r.get("tool") != tool:
            continue
        if status is not None and r.get("status") != status:
            continue
        if idempotency_key is not None and r.get("idempotency_key") != idempotency_key:
            continue
        r_created = _dt_from_row(r.get("created_at"))
        if r_created is None:
            continue
        if ca and r_created < ca:
            continue
        if cb and r_created > cb:
            continue
        filtered.append(r)

    # Sort by created_at desc, tie-break by id desc for stable pagination
    def _sort_key(r):
        dtv = _dt_from_row(r.get("created_at")) or datetime.datetime.min
        return (dtv, r.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    # Apply cursor (created_at, id) to continue after that item in this ordering
    if cursor_created_at is not None and cursor_id is not None:
        # Find first item strictly "after" cursor in desc ordering => items with (created_at,id) < cursor tuple
        cdt = _dt_from_row(cursor_created_at)
        if cdt is None:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        out = []
        for r in filtered:
            rdt = _dt_from_row(r.get("created_at")) or datetime.datetime.min
            rid = r.get("id") or ""
            if (rdt, rid) < (cdt, cursor_id):
                out.append(r)
        filtered = out

    page = filtered[:limit]
    has_more = len(filtered) > len(page)
    next_cursor = None
    if page:
        last = page[-1]
        last_created = last.get("created_at") or ""
        last_id = last.get("id") or ""
        token = f"{last_created}|{last_id}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    # Record read usage: requests collection is reserved for tool calls only; do not create a requests row for list.
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    # Return envelope
    items = []
    for r in page:
        items.append({
            "id": r.get("id"),
            "tool": r.get("tool"),
            "status": r.get("status"),
            "idempotency_key": r.get("idempotency_key"),
            "normalized_target": r.get("normalized_target"),
            "http_status": r.get("http_status"),
            "tokens_used": r.get("tokens_used"),
            "result_count": r.get("result_count"),
            "error_code": r.get("error_code"),
            "error_message": r.get("error_message"),
            "created_at": r.get("created_at"),
            "started_at": r.get("started_at"),
            "finished_at": r.get("finished_at"),
            "updated_at": r.get("updated_at"),
        })

    return {
        "ok": True,
        "data": items,
        "pagination": {
            "limit": limit,
            "total": len(filtered) + (0),  # total after cursor; typical APIs return total for the filtered set (not always). Keep practical.
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "latency_ms": int((time.time() - t0) * 1000)
    }

