def tavily_requests_cancel(api_key, request_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0424000" if __import__("os").path.isdir("./environment_mix/0424000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utc_now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    now = _utc_now()

    # validation
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(request_id, str) or not request_id.strip():
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string")

    # auth: match by id OR key_prefix (never by hash)
    api_keys = _load("api_keys.json")
    key_row = None
    for r in api_keys:
        if r.get("id") == api_key:
            key_row = r
            break
    if key_row is None:
        for r in api_keys:
            if r.get("key_prefix") == api_key:
                key_row = r
                break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")

    reqs = _load("requests.json")
    jobs = _load("crawl_jobs.json")

    rid = request_id.strip()
    req_idx = None
    req_row = None
    for i, r in enumerate(reqs):
        if r.get("id") == rid and r.get("api_key_id") == key_row.get("id"):
            req_idx = i
            req_row = r
            break
    if req_row is None:
        return _err("NOT_FOUND", "Request not found")

    if req_row.get("tool") not in ("tavily-crawl", "tavily-map"):
        return _err("CONFLICT", "Request is not cancelable")

    cur = req_row.get("status")
    if cur == "cancelled":
        # idempotent cancel: return current state
        return {"request": req_row, "cancelled": True, "idempotent": True}

    # Allow cancel from queued/running; if already terminal, return existing request (idempotent success)
    if cur in ("succeeded", "failed"):
        return {"request": req_row, "cancelled": False, "idempotent": True, "status": cur}

    if cur not in ("queued", "running"):
        return _err("INVALID_TRANSITION", "Request cannot be cancelled from its current status", status=cur)

    # update request status transition
    req_row["status"] = "cancelled"
    req_row["finished_at"] = _iso(now)
    req_row["updated_at"] = _iso(now)
    reqs[req_idx] = req_row

    # update job if present (best-effort; if missing, still cancel request)
    job_updated = False
    for j in jobs:
        if j.get("request_id") == rid:
            jcur = j.get("status")
            if jcur in ("queued", "running"):
                j["status"] = "cancelled"
                j["finished_at"] = _iso(now)
                j["updated_at"] = _iso(now)
                job_updated = True
            break

    _save("requests.json", reqs)
    _save("crawl_jobs.json", jobs)

    return {"request": req_row, "job_cancelled": job_updated}

def tavily_crawl_jobs_get(api_key, job_id, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0424000" if __import__("os").path.isdir("./environment_mix/0424000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # --------- validate inputs ----------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(job_id, str) or not job_id.strip():
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string")

    # --------- load datastore ----------
    api_keys = _load("api_keys.json")
    requests_rows = _load("requests.json")
    jobs = _load("crawl_jobs.json")
    web_resources = _load("web_resources.json")

    # Some stores may be {"rows":[...]} shaped; normalize to list
    if isinstance(api_keys, dict) and "rows" in api_keys:
        api_keys = api_keys.get("rows") or []
    if isinstance(requests_rows, dict) and "rows" in requests_rows:
        requests_rows = requests_rows.get("rows") or []
    if isinstance(jobs, dict) and "rows" in jobs:
        jobs = jobs.get("rows") or []
    if isinstance(web_resources, dict) and "rows" in web_resources:
        web_resources = web_resources.get("rows") or []

    # --------- resolve job ----------
    job = None
    for j in jobs:
        if j.get("id") == job_id:
            job = j
            break
    if job is None:
        # Be permissive: if caller passes a request_id by mistake, accept it
        for j in jobs:
            if j.get("request_id") == job_id:
                job = j
                break
    if job is None:
        # Cannot log into requests.json without a known api_key_id and tool in enum; return NOT_FOUND
        return _err("NOT_FOUND", "Crawl job not found")

    # --------- resolve parent request (ownership check depends on it) ----------
    parent_req = None
    req_id = job.get("request_id")
    if isinstance(req_id, str) and req_id:
        for r in requests_rows:
            if r.get("id") == req_id:
                parent_req = r
                break
    if parent_req is None:
        # Orphaned job; treat as not found for callers
        return _err("NOT_FOUND", "Crawl job not found")

    # --------- authenticate api_key parameter ----------
    # IMPORTANT: must not compare against stored key_hash (plaintext is not in the store).
    # Accept either api_keys.id or api_keys.key_prefix.
    presented = api_key.strip()

    key_row = None
    for k in api_keys:
        if k.get("id") == presented or k.get("key_prefix") == presented:
            key_row = k
            break

    # If not matched, attempt a best-effort "prefix derived from token" match:
    # Many systems expose only first N chars in UI; callers sometimes paste full token.
    if key_row is None and len(presented) >= 6:
        pref = presented[:8]
        for k in api_keys:
            kp = k.get("key_prefix")
            if isinstance(kp, str) and (kp == pref or presented.startswith(kp)):
                key_row = k
                break

    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    # If key not active, per tool description: FORBIDDEN (note: global error codes don't include FORBIDDEN;
    # map to UNAUTHORIZED to stay within allowed codes, but preserve meaning in message).
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")

    # --------- ownership check ----------
    if parent_req.get("api_key_id") != key_row.get("id"):
        return _err("NOT_FOUND", "Crawl job not found")

    # --------- build response ----------
    base_wr = None
    base_id = job.get("base_web_resource_id")
    if isinstance(base_id, str) and base_id:
        for w in web_resources:
            if w.get("id") == base_id:
                base_wr = w
                break

    # --------- audit/usage dynamics ----------
    # The schema has no dedicated audit log collection besides requests.json. This endpoint is not a tool invocation
    # (requests.tool enum doesn't include it), so we cannot append to requests.json without violating schema.
    # We still update last_used_at and updated_at for the key to reflect access without changing quotas/counters.
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    # persist api_keys update
    # preserve original file shape (list vs {"rows":[...]})
    api_keys_file = _load("api_keys.json")
    if isinstance(api_keys_file, dict) and "rows" in api_keys_file:
        # update in-place by id
        rows = api_keys_file.get("rows") or []
        for i, k in enumerate(rows):
            if k.get("id") == key_row.get("id"):
                rows[i] = key_row
                break
        api_keys_file["rows"] = rows
        _save("api_keys.json", api_keys_file)
    else:
        for i, k in enumerate(api_keys):
            if k.get("id") == key_row.get("id"):
                api_keys[i] = key_row
                break
        _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "job": {
            "id": job.get("id"),
            "request_id": job.get("request_id"),
            "mode": job.get("mode"),
            "status": job.get("status"),
            "base_web_resource_id": job.get("base_web_resource_id"),
            "base_url": (base_wr.get("canonical_url") if isinstance(base_wr, dict) else None),
            "max_depth": job.get("max_depth"),
            "max_pages": job.get("max_pages"),
            "allowed_path_prefixes": job.get("allowed_path_prefixes"),
            "blocked_path_prefixes": job.get("blocked_path_prefixes"),
            "same_host_only": job.get("same_host_only"),
            "fetch_content": job.get("fetch_content"),
            "pages_discovered": job.get("pages_discovered"),
            "pages_fetched": job.get("pages_fetched"),
            "started_at": job.get("started_at"),
            "finished_at": job.get("finished_at"),
            "created_at": job.get("created_at"),
            "updated_at": job.get("updated_at"),
        },
        "meta": {
            "api_key_id": key_row.get("id"),
            "latency_ms": latency_ms,
            "ts": now_iso,
        },
    }

def tavily_request_results_list(api_key, request_id, result_type=None, include_web_resource=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0424000" if __import__("os").path.isdir("./environment_mix/0424000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # validation
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(request_id, str) or not request_id.strip():
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string")
    if result_type is not None:
        if not isinstance(result_type, str) or result_type not in {"search_hit", "extracted", "crawled_page", "mapped_url"}:
            return _err("VALIDATION_ERROR", "result_type must be one of: search_hit, extracted, crawled_page, mapped_url")
    if include_web_resource is not None and not isinstance(include_web_resource, bool):
        return _err("VALIDATION_ERROR", "include_web_resource must be a boolean")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1:
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
    if limit > 500:
        limit = 500
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # auth: match by id OR key_prefix (never by hash)
    api_keys = _load("api_keys.json")
    key_row = None
    for r in api_keys:
        if r.get("id") == api_key:
            key_row = r
            break
    if key_row is None:
        for r in api_keys:
            if r.get("key_prefix") == api_key:
                key_row = r
                break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")

    reqs = _load("requests.json")
    parent = None
    for r in reqs:
        if r.get("id") == request_id:
            parent = r
            break
    if parent is None or parent.get("api_key_id") != key_row.get("id"):
        return _err("NOT_FOUND", "Request not found")

    results = _load("request_results.json")
    filtered = []
    for row in results:
        if row.get("request_id") != request_id:
            continue
        if result_type is not None and row.get("result_type") != result_type:
            continue
        filtered.append(row)

    # stable ordering by rank (when present) then created_at then id
    def _rank_key(r):
        rk = r.get("rank")
        if isinstance(rk, int) and rk >= 1:
            rank_part = rk
            has_rank = 0
        else:
            rank_part = 10**12
            has_rank = 1
        created = _parse_iso(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (has_rank, rank_part, created, r.get("id") or "")

    filtered.sort(key=_rank_key)

    # cursor is opaque; accept either:
    # - base64("offset:<n>")
    # - a raw row id (start after that id in the sorted list)
    offset = 0
    if cursor:
        cur = cursor.strip()
        parsed = False
        try:
            decoded = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")  # tolerate missing padding
            s = decoded.decode("utf-8", errors="ignore")
            if s.startswith("offset:"):
                n = int(s.split(":", 1)[1])
                if n >= 0:
                    offset = n
                    parsed = True
        except Exception:
            parsed = False
        if not parsed:
            # treat as "after_id"
            for idx, r in enumerate(filtered):
                if r.get("id") == cur:
                    offset = idx + 1
                    parsed = True
                    break
        if not parsed:
            # relax: unknown cursor -> treat as 0 rather than failing validation
            offset = 0

    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(filtered)
    next_cursor = None
    if has_more:
        token = f"offset:{next_offset}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    if include_web_resource:
        wrs = _load("web_resources.json")
        by_id = {w.get("id"): w for w in wrs if isinstance(w, dict) and w.get("id")}
        for r in page:
            wr = by_id.get(r.get("web_resource_id"))
            if wr:
                r["web_resource"] = {
                    "id": wr.get("id"),
                    "canonical_url": wr.get("canonical_url"),
                    "host": wr.get("host"),
                    "title": wr.get("title"),
                    "description": wr.get("description"),
                    "content_mime_type": wr.get("content_mime_type"),
                    "http_status_last": wr.get("http_status_last"),
                    "fetched_at": wr.get("fetched_at"),
                }
            else:
                r["web_resource"] = None

    return {
        "request": {"id": parent.get("id"), "tool": parent.get("tool"), "status": parent.get("status")},
        "results": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "offset": offset,
        },
    }
